import { createFetchStripeSignatureDirectly } from './signature/createFetchStripeSignatureDirectly';
import { supportsFetchAppEmbeddedKey } from './api/supportsFetchAppEmbeddedKey';
import { connectionSettings } from './signature/connectionSettings';
import { getHostEndpoint } from './_endpoint';
/** @public */
export const fetchStripeSignature = async (additionalPayload) => {
    if (await supportsFetchAppEmbeddedKey()) {
        const fetchStripeSignatureDirectly = createFetchStripeSignatureDirectly(connectionSettings);
        return fetchStripeSignatureDirectly(additionalPayload);
    }
    else {
        return getHostEndpoint().call.fetchStripeSignature(additionalPayload);
    }
};
